// Format daily report
const hotel = $('Loop Hotels (Daily)').item.json;
const stats = $input.item.json;

const total = (stats.ai_handled || 0) + (stats.human_handled || 0);
const aiRate = total > 0 ? ((stats.ai_handled / total) * 100).toFixed(1) : '0';
const avgResponseSec = stats.avg_response_time ? (stats.avg_response_time / 1000).toFixed(1) : 'N/A';

const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const dateStr = yesterday.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });

const message = `☀️ *Good Morning! Daily Report*

🏨 *${hotel.hotel_name}*
📅 ${dateStr}

*Yesterday's Summary*

💬 WhatsApp Messages: ${stats.whatsapp_messages || 0}
📞 Phone Calls: ${stats.phone_calls || 0}
📈 Total Interactions: ${(stats.whatsapp_messages || 0) + (stats.phone_calls || 0)}

*Performance*
🤖 AI Handled: ${stats.ai_handled || 0}
👤 Human Handled: ${stats.human_handled || 0}
📈 AI Success Rate: ${aiRate}%
🔄 Handoffs: ${stats.total_handoffs || 0}
⏱ Avg Response: ${avgResponseSec}s

_Have a great day!_ ☕`;

return {
  json: {
    ...hotel,
    reportMessage: message
  }
};

// Format weekly report with comparison
const hotel = $('Loop Hotels (Weekly)').item.json;
const stats = $input.item.json;

const total = (stats.ai_handled || 0) + (stats.human_handled || 0);
const aiRate = total > 0 ? ((stats.ai_handled / total) * 100).toFixed(1) : '0';
const avgResponseSec = stats.avg_response_time ? (stats.avg_response_time / 1000).toFixed(1) : 'N/A';

const today = new Date();
const weekStart = new Date(today);
weekStart.setDate(today.getDate() - 7);

const dateRange = `${weekStart.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })} - ${new Date(today.setDate(today.getDate() - 1)).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}`;

const message = `📊 *Weekly Performance Report*

🏨 *${hotel.hotel_name}*
📅 ${dateRange}

*Communication Volume*
💬 WhatsApp Messages: ${stats.whatsapp_messages || 0}
📞 Phone Calls: ${stats.phone_calls || 0}
📈 Total Interactions: ${(stats.whatsapp_messages || 0) + (stats.phone_calls || 0)}

*Automation Performance*
🤖 AI Handled: ${stats.ai_handled || 0}
👤 Human Handled: ${stats.human_handled || 0}
📈 AI Success Rate: ${aiRate}%

*Handoff Analysis*
🔄 Total Handoffs: ${stats.total_handoffs || 0}
  📉 Low Confidence: ${stats.handoffs_confidence || 0}
  🔧 Complex Request: ${stats.handoffs_complex || 0}
  👋 User Requested: ${stats.handoffs_user || 0}
  😤 Upset Customer: ${stats.handoffs_angry || 0}

*Response Time*
⏱ Avg Response: ${avgResponseSec}s

*Activity*
📆 Days with data: ${stats.days_with_data || 0}/7

_Here's to another great week!_ 🎯`;

return {
  json: {
    ...hotel,
    reportMessage: message
  }
};
